CREATE COLUMN TABLE "TEST_AP"."AWD5" ("AbsEntry" INTEGER CS_INT NOT NULL , "LineId" INTEGER CS_INT NOT NULL , "WTCode" NVARCHAR(4) NOT NULL , "ExpnsCode" INTEGER CS_INT NOT NULL , "DateFrom" LONGDATE CS_LONGDATE NOT NULL , "DateTo" LONGDATE CS_LONGDATE, "DataSource" NVARCHAR(1) DEFAULT 'N', "UpdateDate" LONGDATE CS_LONGDATE, "LogInstanc" INTEGER CS_INT DEFAULT 0 NOT NULL , PRIMARY KEY ("AbsEntry", "LineId", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "AWD5_EXPNSCODE" ON "TEST_AP"."AWD5" ( "WTCode" ASC, "ExpnsCode" ASC, "DateFrom" ASC, "LogInstanc" ASC )